--是否解锁奖池
function HalloweenUtils.IsUnlockRewardPool(poolId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
    local t = comp:GetQuestInfo()

    return checkNumber(t.newUnlockPoolId) >= checkNumber(poolId)
end

--是否可以看剧情
function HalloweenUtils.IsCanShowPlot(poolId)
    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(poolId)
    if not vo then
        return false
    end
    
    if vo.plotId > 0 then
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(vo.plotId)
        if not questVo then
            return false
        end
        
        if checkNumber(questVo.unlockPool) == 0 then
            return true
        end
        
        local isFinish = HalloweenUtils.IsRewardLimitPoolFinish(questVo.unlockPool)
        return isFinish
    end
    
    return true
end 

