function HalloweenUtils.GetReardsNum(poolId, type)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
    local t = HalloweenUtils.GetPoolAllReward(poolId, type)

    local allNum = 0
    local drawNum = 0
    for k, v in pairs(t) do
        drawNum = drawNum + HalloweenUtils.GetRewardDrawNum(v)
        local vo = HalloweenUtils.GetHalloweenPoolRewardVo(v)
        allNum = allNum + checkNumber(vo.stock)
    end
    return allNum, (allNum - drawNum)
end

--是否奖池所有都领取了
function HalloweenUtils.IsRewardPoolFinish(poolId)
    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(poolId)
    if not vo then
        return false
    end
    --无限
    if checkNumber(vo.total) == -1 then
        return false
    end

    local curNum = HalloweenUtils.GetRewardPoolDrawNum(poolId)
    return curNum >= checkNumber(vo.total)
end

--是否可以十连
function HalloweenUtils.IsCanTenDraw(poolId)
    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(poolId)
    if not vo then
        return false
    end
    --无限
    if checkNumber(vo.total) == -1 then
        return true
    end

    local curNum = HalloweenUtils.GetRewardPoolDrawNum(poolId)
    return (checkNumber(vo.total) - curNum) >= 10
end

--剩余抽奖次数
function HalloweenUtils.GetDrawNum(poolId)
    local vo = HalloweenUtils.GetHalloweenRewardPoolVo(poolId)
    if not vo then
        return 0
    end
    --无限
    if checkNumber(vo.total) == -1 then
        local drawNum = 10
        local canNum = math.floor(GoodsUtils.GetThingNo(vo.consumeId) / checkNumber(vo.consumeNumSingle))
        if checkNumber(canNum) <= drawNum then
            drawNum = canNum
        end
        if drawNum > 10 then
            drawNum = 10
        end
        if drawNum <= 0 then
            drawNum = 1
        end
        return drawNum
    end

    local curNum = HalloweenUtils.GetRewardPoolDrawNum(poolId)
    local drawNum = (checkNumber(vo.total) - curNum)

    local canNum = math.floor(GoodsUtils.GetThingNo(vo.consumeId) / checkNumber(vo.consumeNumSingle))
    if checkNumber(canNum) <= checkNumber(drawNum) then
        drawNum = canNum
    end
    if drawNum > 10 then
        drawNum = 10
    end
    if drawNum <= 0 then
        drawNum = 1
    end
    return drawNum
end

--奖池领取数量
function HalloweenUtils.GetRewardPoolDrawNum(poolId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
    local t = comp:GetPoolCallInfo()
    return checkNumber(t[checkString(poolId)])
end 

--奖励领取数量
function HalloweenUtils.GetRewardDrawNum(rewardId)
    local vo = HalloweenUtils.GetHalloweenPoolRewardVo(rewardId)
    if not vo then
        return 0
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
    local t = comp:GetDrawPoolRewards()

    local _t = checkTable(t[checkString(vo.pools)])
    return checkNumber(_t[checkString(rewardId)])
end

--进入入口
function HalloweenUtils.OpenUIJackpotDungoenMainDialog(activityUuid, prefabId, excludeDialogs)
    local dialogId = 0
    if checkNumber(prefabId) == 120901 then
        dialogId = Constants.UITypeIds.UIJackpotDungoenMainDialog
    end
    if checkNumber(dialogId) <= 0 then
        return
    end 

    xRecord.record('10-005', "enter_activity_page_"..activityUuid)
    CS.Engine.UI.UIModule.OpenDialog({ id = dialogId, parameters = {activityUuid = activityUuid} }, checkTable(excludeDialogs))
end

