function HalloweenUtils.GetUuid()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
    return comp:GetUuid()
end

--是否开
function HalloweenUtils.IsOpen()
    local ActivityMgr = import('Game.Activity.ActivityMgr')
    local ActivityConstants = import("Game.Activity.ActivityConstants")

    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return false
    end

    local data = nil
    local uuId = HalloweenUtils.GetUuid()
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.HalloweenQuest and checkNumber(v.id) == checkNumber(uuId) then
            data = v
            break
        end
    end
    if data then
        return os.time() <= checkInt(data.closeTime)
    end
    return false
end

--顶部货币
function HalloweenUtils.GetShowGoods(activityId)
    local vo = HalloweenUtils.GetHalloweenPlanVo(activityId)
    if not vo then
        return {}
    end

    return CfUtils.Split(vo.token)
end

